create table if not exists student_profiles (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null unique references auth.users(id), full_name text, institutional_email text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists student_complaints (id uuid primary key default gen_random_uuid(), student_id uuid not null references student_profiles(id) on delete cascade, title text not null, description text not null, category text check (category in ('Library','Student Welfare','Hostel','Proctor','Gym','Food & Mess')), subcategory text, urgency text check (urgency in ('Low','Medium','High')), classification_reason text, needs_clarification boolean not null default false, clarification_question text, status text not null default 'Draft' check (status in ('Draft','Processing','Awaiting Approval','Approved','Sent','Failed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists authority_mappings (id uuid primary key default gen_random_uuid(), category text not null unique check (category in ('Library','Student Welfare','Hostel','Proctor','Gym','Food & Mess')), authority_name text not null, official_email text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists letter_drafts (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references student_complaints(id) on delete cascade, version integer not null, recipient_name text not null, recipient_email text not null, subject text not null, body text not null, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(complaint_id,version));
create table if not exists email_logs (id uuid primary key default gen_random_uuid(), complaint_id uuid not null references student_complaints(id), draft_id uuid not null references letter_drafts(id), recipient_email text not null, provider_message_id text, status text not null, error_code text, created_at timestamptz not null default now(), sent_at timestamptz);
create index if not exists idx_student_complaints_student_created on student_complaints(student_id, created_at desc);
